namespace sv_d451daee2d7249d4bb82ea63c5a05ba1.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds theme state for a single circuit.
/// All interactive components in the same circuit share this instance.
/// </summary>
public sealed class ThemeService : IDisposable
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// Interactive components subscribe to this to call StateHasChanged.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();

    public void Dispose() => OnChange = null;
}

@*
    Interactive island embedded in the static MainLayout header.
    Because it's interactive, it shares the circuit-scoped ThemeService
    with every other interactive component on the page.
*@
@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="badge rounded-pill"
      style="background-color: @ThemeSvc.AccentColor; color: white;"
      title="Current theme">
    @GetThemeIcon() @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeSvc.Theme switch
    {
        Theme.Light  => "☀️",
        Theme.Dark   => "🌙",
        Theme.System => "💻",
        _            => "🎨"
    };

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px; border-color: @ThemeSvc.AccentColor;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var t in Enum.GetValues<Theme>())
            {
                <button class="btn @(ThemeSvc.Theme == t ? "btn-primary" : "btn-outline-primary")"
                        style="@(ThemeSvc.Theme == t ? $"background-color:{ThemeSvc.AccentColor};border-color:{ThemeSvc.AccentColor}" : "")"
                        @onclick="() => ThemeSvc.Theme = t">
                    @t
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="e => ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd"" />
            <span class="text-muted">@ThemeSvc.AccentColor</span>
        </div>

        <div class="alert mt-3" style="background-color: @ThemeSvc.AccentColor; color: white;">
            Preview: Current theme is <strong>@ThemeSvc.Theme</strong>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

